'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepEqual(Object.keys(api).sort(), ['createGlossary']);
const { createGlossary } = api;

assert.throws(() => createGlossary(null), TypeError);
assert.throws(() => createGlossary({}), TypeError);
for (const entry of [
  null,
  [],
  { term: '', categories: [] },
  { term: '   ', categories: [] },
  { term: 1, categories: [] },
  { term: 'term', categories: 'category' },
  { term: 'term', categories: [''] },
  { term: 'term', categories: ['  '] },
  { term: 'term', categories: [1] }
]) {
  assert.throws(() => createGlossary([entry]), TypeError);
}
assert.throws(
  () => createGlossary([
    { term: ' JavaScript ', categories: ['language'] },
    { term: 'javascript', categories: ['duplicate'] }
  ]),
  error => error instanceof Error && error.message === 'Duplicate term: javascript'
);

const empty = createGlossary([]);
assert.deepEqual(empty.review([]), []);
assert.deepEqual(empty.review(['unknown']), [
  { token: 'unknown', known: false, canonical: null, categories: [] }
]);

const entries = [
  { term: ' JavaScript ', categories: [' Language ', ' Web '] },
  { term: 'Node.js', categories: [] },
  { term: 'API', categories: ['Interface'] }
];
const glossary = createGlossary(entries);
entries[0].term = 'Changed';
entries[0].categories[0] = 'Mutated';
entries.push({ term: 'Later', categories: ['New'] });

const reviewed = glossary.review(['javascript', 'NODE.JS', 'Api', 'missing', '', 'JavaScript']);
assert.deepEqual(reviewed, [
  { token: 'javascript', known: true, canonical: 'JavaScript', categories: ['Language', 'Web'] },
  { token: 'NODE.JS', known: true, canonical: 'Node.js', categories: [] },
  { token: 'Api', known: true, canonical: 'API', categories: ['Interface'] },
  { token: 'missing', known: false, canonical: null, categories: [] },
  { token: '', known: false, canonical: null, categories: [] },
  { token: 'JavaScript', known: true, canonical: 'JavaScript', categories: ['Language', 'Web'] }
]);
assert.throws(() => glossary.review(null), TypeError);
assert.throws(() => glossary.review('JavaScript'), TypeError);
assert.throws(() => glossary.review(['valid', 2]), TypeError);

reviewed[0].canonical = 'Broken';
reviewed[0].categories.push('Broken');
reviewed[1].categories.push('Broken');
const again = glossary.review(['JAVASCRIPT', 'node.js']);
assert.deepEqual(again, [
  { token: 'JAVASCRIPT', known: true, canonical: 'JavaScript', categories: ['Language', 'Web'] },
  { token: 'node.js', known: true, canonical: 'Node.js', categories: [] }
]);
assert.notStrictEqual(again[0].categories, glossary.review(['javascript'])[0].categories);

